// Boundary check of the 1 MiB import limit, using the real app/backup.js. Changes nothing in the repo.
const path = require('path');
const backup = require(path.resolve(process.argv[2], 'app/backup.js'));
const { MAX_IMPORT_BYTES, MESSAGES, toBackupText, tooBigToImport, importBackup } = backup;

const bytes = (s) => new TextEncoder().encode(s).length;

// A real, valid backup (made by toBackupText) whose UTF-8 size is exactly `target` bytes, padded via the title.
function backupOfSize(target, fill = 'a') {
  const make = (title) => toBackupText([{ id: 'x1', title, done: false, createdAt: 1767225600000 }]);
  const base = bytes(make('t'));
  const per = bytes(fill);
  const room = target - base;
  if (room % per !== 0) throw new Error('cannot hit size exactly with this fill');
  return make('t' + fill.repeat(room / per));
}

function fakeStore() {
  const s = { readError: false, writes: 0, replace() { s.writes++; return 'saved'; }, save() { return 'saved'; } };
  return s;
}

async function run(label, text) {
  const file = new Blob([text], { type: 'application/json' });
  const store = fakeStore();
  const res = await importBackup({ store, current: [], file, ask: async () => true });
  const outcome = res.message === MESSAGES.fileTooBig ? 'REJECTED fileTooBig'
    : res.message === MESSAGES.imported.replace('{n}', '1') ? 'IMPORTED' : `other: ${res.message}`;
  console.log(`${label.padEnd(34)} bytes=${String(bytes(text)).padStart(7)} blob.size=${String(file.size).padStart(7)} ` +
    `chars=${String(text.length).padStart(7)} tooBigToImport=${tooBigToImport(text)} importBackup=${outcome} replaceCalls=${store.writes}`);
  return { tooBig: tooBigToImport(text), rejected: res.message === MESSAGES.fileTooBig, imported: store.writes === 1 };
}

(async () => {
  console.log('MAX_IMPORT_BYTES =', MAX_IMPORT_BYTES);
  const r = {};
  r.under = await run('ASCII, limit - 1', backupOfSize(MAX_IMPORT_BYTES - 1));
  r.exact = await run('ASCII, exactly limit', backupOfSize(MAX_IMPORT_BYTES));
  r.over = await run('ASCII, limit + 1', backupOfSize(MAX_IMPORT_BYTES + 1));
  // Multibyte: 'ệ' is 3 bytes in UTF-8, so characters < limit while bytes = limit + 1 (the limit must count bytes).
  const base = bytes(backupOfSize(bytes(toBackupText([{ id: 'x1', title: 't', done: false, createdAt: 1767225600000 }]))));
  const room = MAX_IMPORT_BYTES - base;
  const mbExact = backupOfSize(base + room - (room % 3), 'ệ');
  const pad = MAX_IMPORT_BYTES - bytes(mbExact); // 0..2 ASCII bytes left; add as trailing whitespace (valid JSON)
  r.mbExact = await run('UTF-8 3-byte, exactly limit', mbExact + ' '.repeat(pad));
  r.mbOver = await run('UTF-8 3-byte, limit + 1', mbExact + ' '.repeat(pad + 1));

  const ok =
    !r.under.tooBig && !r.under.rejected && r.under.imported &&
    !r.exact.tooBig && !r.exact.rejected && r.exact.imported &&
    r.over.tooBig && r.over.rejected && !r.over.imported &&
    !r.mbExact.tooBig && !r.mbExact.rejected && r.mbExact.imported &&
    r.mbOver.tooBig && r.mbOver.rejected && !r.mbOver.imported;
  console.log(ok ? 'RESULT: limit is exact (== limit passes, limit + 1 rejected) in both checks' : 'RESULT: MISMATCH');
  process.exit(ok ? 0 : 1);
})();

